mapper.insert:
INSERT INTO meal_feedback (
    content,
    meal_id,
    group_member_id
) VALUES (
    #{content},
    #{mealId},
    #{groupMemberId}
)

mapper.update:
UPDATE meal_feedback
SET content = #{content}
WHERE meal_feedback_id = #{mealFeedbackId}

mapper.select:
SELECT COUNT(1) > 0
FROM meal_feedback
WHERE meal_id = #{mealId}

mapper.delete:
DELETE FROM meal_feedback
WHERE group_member_id IN (
SELECT group_member_id
FROM group_member
WHERE group_id = #{groupId}
)
